import{_ as t}from"./chunks/panneau-daimon.Dp4VEGF4.js";import{_ as a,o as n,c as o,a2 as i}from"./chunks/framework.D9E58p8B.js";const u=JSON.parse('{"title":"Mental model","description":"","frontmatter":{"title":"Mental model"},"headers":[],"relativePath":"en/guide/modele-mental.md","filePath":"en/guide/modele-mental.md"}'),r={name:"en/guide/modele-mental.md"};function s(l,e,d,c,h,m){return n(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="mental-model" tabindex="-1">Mental model <a class="header-anchor" href="#mental-model" aria-label="Permalink to &quot;Mental model&quot;">​</a></h1><p>Daimon is a tool, not an assistant. Your AI client queries it; Daimon perceives or acts, then answers. It calls no AI model and never acts on its own initiative.</p><h2 id="the-organs" tabindex="-1">The organs <a class="header-anchor" href="#the-organs" aria-label="Permalink to &quot;The organs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Organ</th><th>Role</th><th>Tools</th><th>Reference</th></tr></thead><tbody><tr><td><strong>Vue</strong> (Sight)</td><td>Visual perception: screenshots of a display, locating text (on-device OCR: Apple Vision on macOS, Windows OCR on Windows), display geometry, calibration</td><td><code>vue_*</code></td><td><a href="/Daimon/en/reference/vue.html">Vue</a></td></tr><tr><td><strong>Touché</strong> (Touch)</td><td>A window&#39;s accessibility tree (macOS accessibility, UI Automation on Windows), or the element under a point</td><td><code>touche_*</code></td><td><a href="/Daimon/en/reference/touche.html">Touché</a></td></tr><tr><td><strong>Mains</strong> (Hands)</td><td>Action: click, type, press, drag, navigate, key combinations, windows and applications</td><td><code>main_*</code></td><td><a href="/Daimon/en/reference/mains.html">Mains</a></td></tr><tr><td><strong>Overlay</strong></td><td>On-screen markers: highlight, spotlight, cursor halo, banner</td><td><code>overlay_*</code></td><td><a href="/Daimon/en/reference/overlay.html">Overlay</a></td></tr><tr><td><strong>Face</strong></td><td>The application itself: icon, panel, setup walkthrough</td><td>none</td><td>this page</td></tr></tbody></table><h2 id="the-panel" tabindex="-1">The panel <a class="header-anchor" href="#the-panel" aria-label="Permalink to &quot;The panel&quot;">​</a></h2><p>A click on the Daimon icon opens the panel. It holds:</p><ul><li>the Mains <strong>ceiling slider</strong>;</li><li>the <strong>AI clients</strong>, with one switch per client;</li><li>the <strong>updates</strong>;</li><li>the <strong>activity log</strong>, whose button opens its folder;</li><li>the <strong>Présence à l&#39;écran</strong> (On-screen presence) setting, which turns the Overlay on;</li><li><strong>Ouvrir le dossier de configuration</strong> (Open the configuration folder).</li></ul><p><img src="'+t+'" alt="The Daimon panel: permissions granted, AI clients, Mains ceiling slider, on-screen presence"></p><p><em>The Daimon panel on macOS, captured by Daimon itself (French interface). The ceiling is set to L4 (autonomy), hence the red button &quot;Désengager l&#39;autonomie L4&quot; (Disengage L4 autonomy).</em></p><h2 id="perceive-then-act" tabindex="-1">Perceive, then act <a class="header-anchor" href="#perceive-then-act" aria-label="Permalink to &quot;Perceive, then act&quot;">​</a></h2><p>A typical exchange: the AI looks (Vue or Touché), decides, then acts (Mains), and can show what it is doing (Overlay). Each Mains action has a level, and the ceiling you set refuses anything above it: see <a href="./plafond-et-exclusions.html">Ceiling and exclusions</a>.</p><h2 id="the-overlay-is-off-by-default" tabindex="-1">The Overlay is off by default <a class="header-anchor" href="#the-overlay-is-off-by-default" aria-label="Permalink to &quot;The Overlay is off by default&quot;">​</a></h2><p>The <code>overlay_*</code> tools always answer <code>ok</code>, even if no overlay window is running: the command is then dropped. Turn on <strong>Présence à l&#39;écran</strong> in the panel to see the markers. A separate process, the helper, draws them; <a href="/Daimon/en/reference/diagnostic.html#daimon-doctor"><code>daimon_doctor</code></a> tells you whether it is alive (key <code>overlay</code>).</p><h2 id="diagnostics" tabindex="-1">Diagnostics <a class="header-anchor" href="#diagnostics" aria-label="Permalink to &quot;Diagnostics&quot;">​</a></h2><p><a href="/Daimon/en/reference/diagnostic.html#daimon-doctor"><code>daimon_doctor</code></a> gives you, in one call, the state of the permissions, their consequences and the active ceiling.</p>',15)])])}const f=a(r,[["render",s]]);export{u as __pageData,f as default};
